 function materialURL(side,id){const component=componentAssetChoice(side,id);if(component)return componentAssetRoot+'items/'+component[0]+'/game-gray.png?v=20261031-1';const y2k=y2kChoice(side,id);if(y2k)return y2kRoot+'items/'+y2k[0]+'/game-gray.png?v=20261031-card-tones-r1';const tail=tailChoice(side,id);if(tail)return tailRoot+'items/'+tail[0]+'/game-gray.png?v=20261031-1';const atlas=atlasHairChoice(side,id);if(atlas)return atlasHairRoot+'items/'+atlas[0]+'/'+side+'-game-gray.png?v=20261031-card-tones-r1';if(baseFrontChoice(side,id))return baseFrontRoot+'front-game-gray.png';const forehead=foreheadChoice(side,id);if(forehead)return foreheadRoot+'items/'+forehead[0]+'/front-game-gray.png';const nb=noBangsChoice(side,id);if(nb)return noBangsRoot+'items/'+nb[0]+'/'+side+'-game-gray.png'+(nb[0]==='twin-low'?'?v=20261026-redraw2b':'');const asym=asymmetryChoice(side,id);if(asym)return asymmetryRoot+'items/'+asym[0]+'/front-game-gray.png';const inspiration=inspirationChoice(side,id);if(inspiration)return inspirationRoot+`items/${inspiration[0]}/front-game-gray.png`;const fantasy=fantasyChoice(side,id);if(fantasy)return fantasyRoot+'items/'+fantasy[0]+'/'+side+'-game-gray.png';const generic=genericRearChoice(side,id);if(generic)return genericRearRoot+`game/${generic[0]}-back-gray.png`;const single=singleChoice(side,id);if(single)return singleRoot+`items/${single[0]}/front-game-gray.png`;if(refinedRear(side,id))return rearRoot+`game/${id}-back-gray.png`;const extra=sclubChoice(side,id);if(extra)return (auditToneKeys.includes(extra[0])?auditToneRoot:sclubToneKeys.includes(extra[0])?sclubToneRoot:sclubRoot)+`items/${extra[0]}/${side}-game-gray.png`;return side==='front'&&id!=='01'?`assets/materials/characters/hair-front-silk-v6/game/${id}-front-gray.png`:'assets/materials/characters/hair-silk-pilot-v1/'+side+'-gray.png';}
 function thumbURL(side,id){const component=componentAssetChoice(side,id);if(component)return componentAssetRoot+'items/'+component[0]+'/master-gray.png?v=20261031-1';const y2k=y2kChoice(side,id);if(y2k)return cardGrayThumbnail(side,id,y2kRoot+'items/'+y2k[0]+'/master-gray.png?v=20261031-card-tones-r1');const tail=tailChoice(side,id);if(tail)return tailRoot+'items/'+tail[0]+'/master-gray.png?v=20261031-1';const atlas=atlasHairChoice(side,id);if(atlas)return cardGrayThumbnail(side,id,atlasHairRoot+'items/'+atlas[0]+'/'+side+'-master-gray.png?v=20261031-card-tones-r1');if(baseFrontChoice(side,id))return baseFrontRoot+'master-gray.png';const forehead=foreheadChoice(side,id);if(forehead)return foreheadRoot+'items/'+forehead[0]+'/front-master-gray.png';const nb=noBangsChoice(side,id);if(nb)return noBangsRoot+'items/'+nb[0]+'/'+side+'-master-gray.png'+(nb[0]==='twin-low'?'?v=20261026-redraw2b':'');const asym=asymmetryChoice(side,id);if(asym)return asymmetryRoot+'items/'+asym[0]+'/master-gray.png';const inspiration=inspirationChoice(side,id);if(inspiration)return inspirationRoot+`items/${inspiration[0]}/front-gray.png`;const fantasy=fantasyChoice(side,id);if(fantasy)return fantasyRoot+'items/'+fantasy[0]+'/master-gray.png';const generic=genericRearChoice(side,id);if(generic)return genericRearRoot+`thumbs/${generic[0]}.png`;const single=singleChoice(side,id);if(single)return singleRoot+`items/${single[0]}/front-gray.png`;if(side==='back'&&id==='01')return 'assets/materials/characters/hair-silk-pilot-v1/back-gray.png';if(refinedRear(side,id))return rearRoot+`game/${id}-master-gray.png`;const extra=sclubChoice(side,id);if(extra)return (auditToneKeys.includes(extra[0])?auditToneRoot:sclubToneKeys.includes(extra[0])?sclubToneRoot:sclubRoot)+`items/${extra[0]}/${side}-gray.png`;return side==='front'?materialURL(side,id):root+`parts/${id}-back-lineart.png`;}
 function open(){if(typeof openWorkspace==='function')openWorkspace('wardrobe');mount();panel.hidden=false;document.querySelector('.wardrobe').classList.add('hair-open');editBar.hidden=false;editOverlay.hidden=false;document.querySelectorAll('.sidebar .nav').forEach(b=>b.classList.toggle('active',b.id==='hair-nav'));saved.enabled=true;save();update();}
 function close(){if(editBar)editBar.hidden=true;if(editOverlay)editOverlay.hidden=true;if(panel)panel.hidden=true;document.querySelector('.wardrobe')?.classList.remove('hair-open');}
 const initialPalette=[['#252b35','自然黑'],['#454039','冷茶棕'],['#79513b','栗棕'],['#a27c58','奶茶棕'],['#c9ad75','亚麻金'],['#b2ada7','雾灰'],['#a97578','玫瑰棕'],['#c88caa','烟粉']];
 saved.palette=Array.isArray(saved.palette)?saved.palette.filter(v=>Array.isArray(v)&&/^#[0-9a-f]{6}$/i.test(v[0])&&typeof v[1]==='string').map(v=>[v[0],v[1].slice(0,24),...(v[2]?.kind==='highlight'?[JSON.parse(JSON.stringify(v[2]))]:[])]):initialPalette.map(v=>[...v]);
 const escapeLabel=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 if(!saved.dyeSchemeVersion){if(hasDye(saved.dye)){saved.legacyDyeScheme=schemeRow(saved.color,'已有挑染');saved.palette.push(saved.legacyDyeScheme);saved.dyeSchemeVersion=1;save();}else saved.dyeSchemeVersion=1;}
 function fillPaletteEditor(){const manager=panel.querySelector('#hair-palette-editor'),index=Number(manager.querySelector('select').value),row=saved.palette[index];manager.querySelector('[data-color-name]').value=row?.[1]||'';manager.querySelector('[data-color-hex]').value=row?.[0]||saved.color;manager.querySelector('[data-color-picker]').value=row?.[0]||saved.color;manager.querySelector('[data-color-delete]').disabled=!row;manager.querySelector('[data-color-status]').textContent='';}
 function renderPalette(selected=-1){panel.querySelector('#hair-pilot').innerHTML=saved.palette.map(([c,n,scheme],i)=>`<button data-hair-color="${c}" data-palette-index="${i}" title="${escapeLabel(n)}" aria-label="发色：${escapeLabel(n)}" style="--hair-swatch:${c}"><i></i><span>${escapeLabel(n)}${scheme?.kind==='highlight'?'<small data-no-i18n>挑染 / Highlights</small>':''}</span></button>`).join('');const select=panel.querySelector('#hair-palette-editor select');select.innerHTML='<option value="-1">新增颜色</option>'+saved.palette.map(([c,n,scheme],i)=>`<option value="${i}">${escapeLabel(n)}${scheme?.kind==='highlight'?' · 挑染 / Highlights':''}</option>`).join('');select.value=String(selected);fillPaletteEditor();}
 function hasDye(dye=dyeDraft){return Object.values(dye||{}).some(v=>Array.isArray(v)&&v.length);}
 function colorSchemeIndex(){const matches=v=>v&&v[0].toLowerCase()===saved.color.toLowerCase()&&JSON.stringify(v[2]?.dye||{})===JSON.stringify(dyeDraft);return matches(saved.palette[saved.activeColorScheme])?saved.activeColorScheme:saved.palette.findIndex(matches);}
 function selectColorScheme(row){if(!row)return;saved.activeColorScheme=saved.palette.indexOf(row);saved.color=row[0];dyeDraft=JSON.parse(JSON.stringify(row[2]?.kind==='highlight'?row[2].dye||{}:{}));saved.dye=JSON.parse(JSON.stringify(dyeDraft));setBrushMode('move');brushColor=saved.color;save();update();}
 function schemeRow(color,name){return [color,name,...(hasDye()?[{kind:'highlight',dye:JSON.parse(JSON.stringify(dyeDraft))}]:[])];}
 function saveColorScheme(color,name,index=-1){if(hasDye()&&saved.palette[index]?.[2]?.kind!=='highlight')index=-1;const row=schemeRow(color,name);if(index<0){saved.palette.push(row);index=saved.palette.length-1;}else saved.palette[index]=row;saved.activeColorScheme=index;saved.dye=JSON.parse(JSON.stringify(dyeDraft));save();return index;}
 function applyDye(canvas,side,id,fit,color){const strokes=dyeDraft[side+':'+id]||[];if(!strokes.length||!window.HairDye)return;const ctx=canvas.getContext('2d'),p=ctx.getImageData(0,0,939,1676);p.data.set(window.HairDye.apply(p.data,939,1676,dyeBox(side,id,fit),strokes,color,JSON.parse(fit.toneRevision||'{}')));ctx.putImageData(p,0,0);}
 function setBrushMode(mode){brushMode=mode;if(!panel)return;panel.querySelectorAll('[data-brush-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.brushMode===mode)));editOverlay?.classList.toggle('dye-active',mode!=='move');}
 function previewColor(color){brushColor=color;if(brushMode==='move'){saved.color=color;dyeDraft={};saved.dye={};}save();update();}
 function pilotControls(){if(panel.querySelector('#hair-pilot'))return;const box=document.createElement('div');box.id='hair-pilot';box.className='hair-recommended-colors';panel.querySelector('.hair-color').after(box);const manager=document.createElement('div');manager.id='hair-palette-editor';manager.innerHTML='<span class="hair-row-title">管理颜色</span><select aria-label="选择要编辑的发色"></select><label><input data-color-name aria-label="颜色名字" maxlength="24" placeholder="例如：冷雾茶棕"></label><label><input data-color-hex aria-label="颜色色号" maxlength="7" placeholder="#79513b" spellcheck="false"><span data-picker-slot></span></label><div><button data-color-save>保存</button><button data-color-delete>删除</button></div><output data-color-status role="status"></output>';box.after(manager);const picker=panel.querySelector('#hair-color');picker.setAttribute('data-color-picker','');manager.querySelector('[data-picker-slot]').replaceWith(picker);panel.querySelector('.hair-color label:last-child').remove();manager.open=true;renderPalette();manager.querySelector('select').onchange=()=>{fillPaletteEditor();selectColorScheme(saved.palette[Number(manager.querySelector('select').value)]);};manager.querySelector('[data-color-picker]').oninput=e=>{manager.querySelector('[data-color-hex]').value=e.target.value;previewColor(e.target.value);};manager.querySelector('[data-color-hex]').oninput=e=>{const hex=e.target.value.startsWith('#')?e.target.value:'#'+e.target.value;if(/^#[0-9a-f]{6}$/i.test(hex)){manager.querySelector('[data-color-picker]').value=hex;previewColor(hex);}};manager.querySelector('[data-color-save]').onclick=()=>{const name=manager.querySelector('[data-color-name]').value.trim(),raw=manager.querySelector('[data-color-hex]').value.trim(),hex=raw.startsWith('#')?raw:'#'+raw,index=Number(manager.querySelector('select').value);if(!name||!/^#[0-9a-f]{6}$/i.test(hex)){manager.querySelector('[data-color-status]').textContent='填写名字和六位色号，如 #79513b';return;}const selected=saveColorScheme(hex.toLowerCase(),name,index);saved.color=hex.toLowerCase();save();publishDefaults();renderPalette(selected);manager.querySelector('[data-color-status]').textContent='已保存';update();};manager.querySelector('[data-color-delete]').onclick=()=>{const index=Number(manager.querySelector('select').value);if(index<0)return;saved.palette.splice(index,1);saved.legacyDyeScheme=null;save();publishDefaults();renderPalette();manager.querySelector('[data-color-status]').textContent='已删除';update();};box.onclick=e=>{const b=e.target.closest('[data-hair-color]');if(!b)return;if(brushMode!=='move'&&saved.palette[Number(b.dataset.paletteIndex)]?.[2]?.kind!=='highlight')previewColor(b.dataset.hairColor);else selectColorScheme(saved.palette[Number(b.dataset.paletteIndex)]);manager.querySelector('select').value=b.dataset.paletteIndex;fillPaletteEditor();save();update();};const zoom=document.createElement('button');zoom.id='hair-zoom';zoom.textContent='看头部';panel.querySelector('.hair-heading').append(zoom);zoom.onclick=()=>{const on=document.querySelector('.figure-wrap').classList.toggle('hair-zoom');zoom.textContent=on?'看全身':'看头部';syncEditor();};}
 function faceControls(){if(panel.querySelector('#hair-eye-reveal'))return;const box=document.createElement('label');box.className='hair-face-control';box.style.cssText='display:flex;align-items:center;gap:10px;margin:12px 0';box.innerHTML='眼部透出<input id="hair-eye-reveal" type="range" min="0" max="75" step="1" aria-label="眼部透出强度"><output id="hair-eye-value"></output>';panel.querySelector('.hair-heading').after(box);box.querySelector('input').oninput=e=>{saved.eyeReveal=Number(e.target.value)/100;save();update();};}
 function hairCategory(side,id){if(hairComponent(side,id))return 'component';if(baseFrontChoice(side,id))return 'front';const category=saved.pieceCategory[side+':'+id];return ['front','back','single','component'].includes(category)?category:side==='front'?'front':'back';}
 function storeHairCategories(){try{localStorage.setItem('wardrobe-hair-categories-v1',JSON.stringify(saved.pieceCategory));}catch(e){}}
 function assignHairCategory(side,id,category){if(!['front','back','single','component'].includes(category))return;saved.pieceCategory[side+':'+id]=category;if(category!=='single')saved.piecePlacement[side+':'+id]=category==='front'?'front':'behind';storeHairCategories();}
 function classifiedHairEntries(){return ['front','back'].flatMap(side=>choices(side).map((name,i)=>{const id=String(i+1).padStart(2,'0');return {side,id,name,category:hairCategory(side,id)};}).filter(e=>!retiredComponent(e.side,e.id)));}
 const hairUIEscape=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let hairCategoryStamp='',hairCategoryFilter='front';
 function renderHairCategories(){
  if(!panel)return;let host=panel.querySelector('#hair-categories');if(!host){host=document.createElement('div');host.id='hair-categories';host.innerHTML='<nav class="hair-category-tabs" aria-label="发型分类">'+[['front','前发'],['back','后发'],['single','Pieces'],['component','组件']].map(([category,label])=>`<button data-hair-filter="${category}">${label}</button>`).join('')+'<button class="hair-category-clear" data-clear-hair-category>取下本分类</button></nav>'+['front','back','single','component'].map(category=>`<details class="hair-section" data-hair-category-section="${category}" open><summary>${{front:'前发',back:'后发',single:'Pieces',component:'组件'}[category]} <span data-category-count></span></summary><div class="hair-grid" data-category-grid></div></details>`).join('');panel.querySelector('.hair-color-section').after(host);host.onclick=e=>{const filter=e.target.closest('[data-hair-filter]');if(filter){hairCategoryFilter=filter.dataset.hairFilter;renderHairCategories();return;}if(e.target.closest('[data-clear-hair-category]')){for(const side of ['front','back']){saved.pieces[side]=selectedPieces(side).filter(id=>hairCategory(side,id)!==hairCategoryFilter);selectPart(side,saved.pieces[side].at(-1)||'none');}save();update();}};host.onchange=e=>{const control=e.target.closest('[data-hair-classify]');if(!control)return;assignHairCategory(control.dataset.side,control.dataset.id,control.value);hairCategoryFilter=control.value;save();update();};}
  panel.querySelectorAll('.hair-part,#fantasy-styles,#inspiration-styles,#asymmetry-styles').forEach(el=>el.hidden=true);
  for(const category of ['front','back','single','component']){host.querySelector(`[data-hair-category-section="${category}"]`).hidden=category!==hairCategoryFilter;host.querySelector(`[data-hair-filter="${category}"]`).setAttribute('aria-pressed',String(category===hairCategoryFilter));}const entries=classifiedHairEntries(),stamp=JSON.stringify([entries,saved.pieces,saved.piecePlacement]);if(stamp===hairCategoryStamp)return;hairCategoryStamp=stamp;
  for(const category of ['front','back','single','component']){const section=host.querySelector(`[data-hair-category-section="${category}"]`),list=entries.filter(e=>e.category===category);section.querySelector('[data-category-count]').textContent='('+list.length+')';section.querySelector('[data-category-grid]').innerHTML=list.map(({side,id,name})=>`<div class="hair-choice"><button data-hair-choice="${id}" data-side="${side}" aria-label="${{front:'前发',back:'后发',single:'Pieces',component:'组件'}[category]}：${hairUIEscape(name)}" aria-pressed="${selectedPieces(side).includes(id)}"><img src="${thumbURL(side,id)}" loading="lazy" alt=""><span>${hairUIEscape(name)}</span></button><div class="hair-layer-buttons">${(category==='front'?[['front','前一层'],['behind','后一层']]:category==='back'?[]:[['front','身体前'],['behind','身体后']]).map(([pos,label])=>`<button data-piece-layer="${pos}" data-piece-id="${id}" data-side="${side}" aria-label="${hairUIEscape(name)}放人物${label}面" aria-pressed="${placement(side,id)===pos}">${label}</button>`).join('')}</div><label class="hair-classify-label">分类<select data-hair-classify data-side="${side}" data-id="${id}" aria-label="${hairUIEscape(name)}分类">${[['front','前发'],['back','后发'],['single','Pieces'],['component','组件']].map(([value,label])=>`<option value="${value}" ${value===category?'selected':''}>${label}</option>`).join('')}</select></label></div>`).join('')||'<p class="hair-category-empty">可在发型的分类选项中移入，支持多选叠加。</p>';}
 }

 function update(){if(!panel)return;hairToneControls();foreheadControls();noBangsControls();asymmetryControls();fantasyControls();inspirationControls();syncEditor();panel.querySelectorAll('[data-piece-layer]').forEach(b=>b.setAttribute('aria-pressed',String(placement(b.dataset.side,b.dataset.pieceId)===b.dataset.pieceLayer)));panel.querySelectorAll('[data-hair-choice]').forEach(b=>{const checked=b.dataset.hairChoice==='none'?!selectedPieces(b.dataset.side).length:selectedPieces(b.dataset.side).includes(b.dataset.hairChoice);b.setAttribute('aria-pressed',String(checked));});panel.querySelector('#hair-saved').textContent=positionStatus;pilotControls();faceControls();for(const s of ['front','back']){panel.querySelector(`[data-hair-part="${s}"]`).value=saved[s];for(const p of ['x','y','scale']){const input=editBar.querySelector(`[data-side="${s}"][data-fit="${p}"]`);if(document.activeElement!==input)input.value=saved[s+'Fit'][p];}}panel.querySelectorAll('[data-hair-color]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.hairColor.toLowerCase()===(brushMode==='move'?saved.color:brushColor).toLowerCase()&&(brushMode!=='move'||Number(b.dataset.paletteIndex)===colorSchemeIndex()))));panel.querySelector('#hair-color').value=brushMode==='move'?saved.color:brushColor;panel.querySelector('#hair-enabled').checked=saved.enabled;panel.querySelector('#hair-eye-reveal').value=Math.round(saved.eyeReveal*100);panel.querySelector('#hair-eye-value').value=Math.round(saved.eyeReveal*100)+'%';renderHairCategories();}
 function dyeBox(side,id,f){const extra=sclubChoice(side,id)||singleChoice(side,id)||fantasyChoice(side,id)||inspirationChoice(side,id)||asymmetryChoice(side,id)||noBangsChoice(side,id)||foreheadChoice(side,id)||baseFrontChoice(side,id)||atlasHairChoice(side,id)||tailChoice(side,id)||y2kChoice(side,id)||componentAssetChoice(side,id);const generic=genericRearChoice(side,id);if(generic)return genericRearBox(generic,f);if(refinedRear(side,id))return rearGeometry(f);if(extra){const b=sclubBounds[extra[0]][side],rx=f.scale/1.2*(f.sx||1),ry=f.scale/1.2*(f.sy||1);return {x:470+(b[0]-470)*rx+f.x,y:180+(b[1]-180)*ry+f.y,w:(b[2]-b[0])*rx,h:(b[3]-b[1])*ry};}return {x:470-90*f.scale*(f.sx||1)+f.x,y:15+f.y,w:180*f.scale*(f.sx||1),h:278*f.scale*(f.sy||1)};}
 function fantasyControls(){if(panel.querySelector('#fantasy-styles'))return;const box=document.createElement('details');box.id='fantasy-styles';box.className='hair-section';box.open=true;box.innerHTML='<summary>编发与层次 · 16款</summary><div style="display:flex;flex-wrap:wrap;gap:6px;padding:10px 0">'+fantasyStyles.map((v,i)=>'<button data-fantasy-index="'+i+'">'+v[1]+' · '+(v[2]==='front'?'前发':'后发')+'</button>').join('')+'</div>';panel.querySelector('.hair-color-section').after(box);box.onclick=e=>{const b=e.target.closest('[data-fantasy-index]');if(!b)return;const style=fantasyStyles[Number(b.dataset.fantasyIndex)];if(!style)return;const side=style[2],id=fantasyID(style);saved.pieces[side]=[id];selectPart(side,id);editSide=side;saved.enabled=true;save();update();};}
 function inspirationControls(){if(panel.querySelector('#inspiration-styles'))return;const box=document.createElement('details');box.id='inspiration-styles';box.className='hair-section';box.open=true;box.innerHTML='<summary>灵感新款 · 稀疏刘海</summary><div style="display:flex;flex-wrap:wrap;gap:6px;padding:10px 0">'+inspirationStyles.map((v,i)=>`<button data-inspiration-style="${i}">${v[1]}</button>`).join('')+'</div><small>前五款整款试戴；空气刘海试戴配齐肩后发，也可在前发中单独选用。</small>';panel.querySelector('.hair-color-section').after(box);box.onclick=e=>{const b=e.target.closest('[data-inspiration-style]');if(!b)return;const n=Number(b.dataset.inspirationStyle),id=String(inspirationOffset+n),back=n===5?'25':'none';saved.pieces.front=[id];saved.pieces.back=back==='none'?[]:[back];selectPart('front',id);selectPart('back',back);if(back!=='none'){if(!saved.positionDefaults.back[back]){saved.backFit=cleanFit({...defaultFit(),scale:.9});saved.positionDefaults.back[back]={...saved.backFit};}saved.piecePlacement['back:'+back]='behind';}saved.piecePlacement['front:'+id]='front';editSide='front';saved.enabled=true;save();update();};}
